package com.rodentcontrol.customer;
import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import java.util.concurrent.Executors;
public class ForgotPasswordActivity extends AppCompatActivity{EditText user,token,pass;TextView msg;protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_forgot);user=findViewById(R.id.username);token=findViewById(R.id.token);pass=findViewById(R.id.password);msg=findViewById(R.id.message);findViewById(R.id.send).setOnClickListener(v->send());findViewById(R.id.reset).setOnClickListener(v->reset());}void send(){Executors.newSingleThreadExecutor().execute(()->{try{Api.forgotPassword(user.getText().toString().trim());runOnUiThread(()->msg.setText("Nếu tài khoản hợp lệ, hướng dẫn đã được gửi tới email bảo mật."));}catch(Exception e){runOnUiThread(()->msg.setText(e.getMessage()));}});}void reset(){Executors.newSingleThreadExecutor().execute(()->{try{Api.resetPassword(token.getText().toString().trim(),pass.getText().toString());runOnUiThread(()->msg.setText("Đổi mật khẩu thành công. Bạn có thể đăng nhập lại."));}catch(Exception e){runOnUiThread(()->msg.setText(e.getMessage()));}});}}
